function e(e,t=`YYYY-MM-DD`){if(!e)return`未知`;let n=new Date(Number(e)*1e3);if(isNaN(n.getTime()))return`未知`;let r=n.getFullYear(),i=String(n.getMonth()+1).padStart(2,`0`),a=String(n.getDate()).padStart(2,`0`),o=String(n.getHours()).padStart(2,`0`),s=String(n.getMinutes()).padStart(2,`0`),c=String(n.getSeconds()).padStart(2,`0`);return t.replace(`YYYY`,String(r)).replace(`MM`,i).replace(`DD`,a).replace(`HH`,o).replace(`mm`,s).replace(`ss`,c)}function t(e){if(!e)return`00:00`;let t=Math.floor(e/60),n=Math.floor(e%60);return`${String(t).padStart(2,`0`)}:${String(n).padStart(2,`0`)}`}function n(e){return e?e>=1e8?(e/1e8).toFixed(1)+`亿`:e>=1e4?(e/1e4).toFixed(1)+`万`:e.toString():`0`}export{t as n,n as r,e as t};